t=open(os.path.normpath(os.environ['RLM_SESSION_DIR'])+'/../../sessions/'+os.path.basename(os.environ['RLM_SESSION_DIR'])+'.jsonl').read().replace('\\n','\n')
G={}
for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
    k,h,w=m[1],int(m[2]),int(m[3])
    rows=[r.split() for r in t[m.end():].split('\n')[:h]]
    if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
        G[k]=[[int(x) for x in r] for r in rows]
from collections import Counter
print(Counter(v for row in G['Test input'] for v in row))

from collections import deque
def comps(g):
    h,w=len(g),len(g[0]); seen=[[False]*w for _ in range(h)]; out=[]
    for i in range(h):
        for j in range(w):
            if not seen[i][j]:
                c=g[i][j]; q=deque([(i,j)]); seen[i][j]=True; cells=[]
                while q:
                    a,b=q.popleft(); cells.append((a,b))
                    for da,db in((1,0),(-1,0),(0,1),(0,-1)):
                        na,nb=a+da,b+db
                        if 0<=na<h and 0<=nb<w and not seen[na][nb] and g[na][nb]==c:
                            seen[na][nb]=True; q.append((na,nb))
                out.append((c,cells))
    return out
cs=comps(G['Test input'])
sizes=Counter((c,len(cells)) for c,cells in cs)
print(len(cs))
print(sorted(set(s for c,cells in cs for s in [len(cells)]))[:20])
sing=[(c,cells) for c,cells in cs if len(cells)==1]
print('singletons:',len(sing), Counter(c for c,_ in sing))

